      + inp(F('mheInspections', 'deficiencies', { wide: true, label: 'What was found' }), v.deficiencies) + inp(F('mheInspections', 'corrective', { wide: true }), v.corrective)
      + inp(F('mheInspections', 'caStatus'), v.caStatus || 'Open') + inp(F('mheInspections', 'caDue'), v.caDue) + inp(F('mheInspections', 'caDone'), v.caDone)
